def read_ints():
    return list(map(int, input().split()))

def main():
    N = int(input())
    g = [read_ints() for _ in range(N)]
    M = int(input())
    queries = [read_ints() for _ in range(M)]

    for k, x in queries:
        # Initialize the set of gnomes who will know the joke after k minutes
        known_gnomes = set()

        # Use a queue to simulate the spread of the joke
        queue = [x]

        # Keep track of the time elapsed
        time = 0

        # Perform BFS to find all gnomes who will know the joke after k minutes
        while queue and time <= k:
            current_level_size = len(queue)
            for _ in range(current_level_size):
                current_gnome = queue.pop(0)
                if current_gnome not in known_gnomes:
                    known_gnomes.add(current_gnome)
                    for friend in range(N):
                        if g[current_gnome - 1][friend] == 1:
                            queue.append(friend + 1)
            time += 1

        # Output the results for the current query
        print(len(known_gnomes))
        if len(known_gnomes) > 0:
            print(" ".join(map(str, sorted(known_gnomes))))
        else:
            print(-1)

if __name__ == "__main__":
